mapper.insert:
/* AppReq07Mapper.insertAttdReq */
INSERT INTO TB_USER_ATTD_REQ (
      REQ_ID
    , CMPNY_CD
    , SITE_CD
    , USER_CD
    , REQ_TYPE
    , TARGET_ID
    , REQ_STATUS
    , REQ_REASON
    , WORK_YMD
    , NODE_CD
    , WORK_SEQ
    , START_DATE
    , START_TIME
    , END_DATE
    , END_TIME
    , SCH_CD
    , DEL_YN
    , INSERT_NO
    , INSERT_DATE
)
VALUES (
      #{reqId}
    , #{cmpnyCd}
    , #{siteCd}
    , #{userCd}
    , #{reqType}
    , #{targetId}
    , #{reqStatus}
    , #{reqReason}
    , #{workYmd}
    , #{nodeCd}
    , #{workSeq}
    , #{startDate}
    , #{startTime}
    , #{endDate}
    , #{endTime}
    , #{schCd}
    , 'N'
    , #{insertNo}
    , NOW()
)

mapper.select:
/* AppReq07Mapper.countDuplicateReq */
SELECT COUNT(1)
  FROM TB_USER_ATTD_REQ A
 WHERE A.CMPNY_CD   = #{cmpnyCd}
   AND A.SITE_CD    = #{siteCd}
   AND A.USER_CD    = #{userCd}
   AND A.WORK_YMD   = #{workYmd}
   AND A.REQ_TYPE   = #{reqType}
   AND A.REQ_STATUS = '01'
   AND A.DEL_YN     = 'N'

/* AppReq07Mapper.selectExistingAttdId */
SELECT A.ATTD_ID
  FROM TB_USER_ATTD_MGMT A
 WHERE A.CMPNY_CD = #{cmpnyCd}
   AND A.SITE_CD  = #{siteCd}
   AND A.USER_CD  = #{userCd}
   AND A.WORK_YMD = #{workYmd}
   AND A.WORK_SEQ = #{workSeq}
   AND A.DEL_YN   = 'N'
 LIMIT 1

/* AppReq07Mapper.selectWorkPlanSchedule */
SELECT S.SCH_CD            AS schCd
     , S.FST_SCH_STR_TIME  AS fstStrTime
     , S.FST_SCH_END_TIME  AS fstEndTime
     , S.SEC_SCH_STR_TIME  AS secStrTime
     , S.SEC_SCH_END_TIME  AS secEndTime
  FROM TB_USER_WORK_PLAN P
  INNER JOIN TB_SCH_MGMT S
     ON S.CMPNY_CD = P.CMPNY_CD
    AND S.SITE_CD  = P.SITE_CD
    AND S.SCH_CD   = P.WORK_PLAN_CD
 WHERE P.CMPNY_CD = #{cmpnyCd}
   AND P.SITE_CD  = #{siteCd}
   AND P.USER_CD  = #{userCd}
   AND P.WORK_YMD = #{workYmd}
 LIMIT 1

/* AppReq07Mapper.countPendingAttdCorrectionBySlot */
SELECT COUNT(1)
  FROM TB_USER_ATTD_REQ A
 WHERE A.CMPNY_CD   = #{cmpnyCd}
   AND A.SITE_CD    = #{siteCd}
   AND A.USER_CD    = #{userCd}
   AND A.WORK_YMD   = #{workYmd}
   AND A.WORK_SEQ   = #{workSeq}
   AND A.REQ_TYPE   IN ('01', '02')
   AND A.REQ_STATUS = '01'
   AND A.DEL_YN     = 'N'

/* AppReq07Mapper.countActiveSchedModify */
SELECT COUNT(1)
  FROM TB_USER_ATTD_REQ A
 WHERE A.CMPNY_CD   = #{cmpnyCd}
   AND A.SITE_CD    = #{siteCd}
   AND A.USER_CD    = #{userCd}
   AND A.WORK_YMD   = #{workYmd}
   AND A.REQ_TYPE   = '10'
   AND A.REQ_STATUS IN ('01', '02')
   AND A.DEL_YN     = 'N'

/* AppReq07Mapper.countActiveOvertimeReq */
SELECT COUNT(1)
  FROM TB_USER_ATTD_REQ A
 WHERE A.CMPNY_CD   = #{cmpnyCd}
   AND A.SITE_CD    = #{siteCd}
   AND A.USER_CD    = #{userCd}
   AND A.WORK_YMD   = #{workYmd}
   AND A.REQ_TYPE   IN ('03', '04')
   AND A.REQ_STATUS IN ('01', '02')
   AND A.DEL_YN     = 'N'

/* AppReq07Mapper.selectActualAttdWindowBySlot */
SELECT A.CHECK_IN_DATE   AS checkInDate
     , A.CHECK_IN_TIME   AS checkInTime
     , A.CHECK_OUT_DATE  AS checkOutDate
     , A.CHECK_OUT_TIME  AS checkOutTime
  FROM TB_USER_ATTD_MGMT A
 WHERE A.CMPNY_CD = #{cmpnyCd}
   AND A.SITE_CD  = #{siteCd}
   AND A.USER_CD  = #{userCd}
   AND A.WORK_YMD = #{workYmd}
   AND A.WORK_SEQ = #{workSeq}
   AND A.DEL_YN   = 'N'
 LIMIT 1

/* AppReq07Mapper.countUserWorkPlan */
SELECT COUNT(1)
  FROM TB_USER_WORK_PLAN P
 WHERE P.CMPNY_CD = #{cmpnyCd}
   AND P.SITE_CD  = #{siteCd}
   AND P.USER_CD  = #{userCd}
   AND P.WORK_YMD = #{workYmd}
